CREATE DATABASE IF NOT EXISTS uav_remote_sensing DEFAULT CHARACTER SET utf8mb4; USE uav_remote_sensing; CREATE TABLE uav_task(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(200) NOT NULL,region VARCHAR(200),algorithm VARCHAR(80),status VARCHAR(30),created_at DATETIME,latitude DOUBLE,longitude DOUBLE); CREATE TABLE interpretation(id BIGINT PRIMARY KEY AUTO_INCREMENT,task_id BIGINT NOT NULL,algorithm VARCHAR(80),source_path VARCHAR(500),mask_path VARCHAR(500),status VARCHAR(30),created_at DATETIME,CONSTRAINT fk_interpret_task FOREIGN KEY(task_id) REFERENCES uav_task(id));
